"use strict";
import { total } from "./cart"

const items = [{ price: 3, qty: 2 }, { price: 5, qty: 1 }]

export function checkout(cart: { price: number; qty: number }[]): number {
  if (cart.length === 0) {
    throw new TypeError("cart has no items")
  }
  return total(cart)
}

console.log("total", checkout(items))
